-- Wayfarer's Tales - rewrite proposals waiting for review (generated from tools/review/rewrites.json).
-- Key = the line's id (as in the Ambiance dev panel). They replace the current text only
-- when the option "Try new lines" is on. Approved ones get moved into SensesData.lua.

local _, KT = ...
local D = KT.Data

D.REWRITES = {
  ["generic:2"] = { en = "You take a deep breath. The fresh air fills your lungs, and a weight seems to lift from your shoulders.",
    fr = "Vous prenez une grande inspiration. L'air frais vous emplit les poumons, et un poids semble quitter vos épaules." },
  ["generic:3"] = { en = "You roll your shoulders, and your tired muscles loosen one by one. It feels good to take a breather.",
    fr = "Vous faites rouler vos épaules, et vos muscles fatigués se dénouent un à un. Ça fait du bien de souffler un instant." },
  ["generic:4"] = { en = "Stars glitter overhead, so many they seem within reach. Beneath that vast sky, you feel tiny.",
    fr = "Les étoiles scintillent au-dessus de vous, si nombreuses qu'elles semblent à portée de main. Face à ce ciel immense, vous vous sentez minuscule." },
  ["generic:5"] = { en = "A ray of sunlight warms your face for a moment. You close your eyes to enjoy it, just for a second.",
    fr = "Un rayon de soleil vous réchauffe un instant le visage. Vous fermez les yeux pour en profiter, juste une seconde." },
  ["generic:6"] = { en = "The night air is cool on your face. You breathe in deeply, and the day's weariness drifts away a little.",
    fr = "L'air de la nuit est frais sur votre visage. Vous inspirez profondément, et la fatigue de la journée s'éloigne un peu." },
  ["generic:7"] = { en = "A rich smell of stew fills the room, with hints of onion and herbs. Your stomach wakes up at once.",
    fr = "Une bonne odeur de ragoût emplit la salle, avec des notes d'oignon et d'herbes. Votre estomac se réveille aussitôt." },
  ["generic:8"] = { en = "The fire crackles in the hearth, casting dancing shadows on the walls. Its warmth draws you in like a magnet.",
    fr = "Le feu crépite dans l'âtre et projette des ombres dansantes sur les murs. Sa chaleur vous attire comme un aimant." },
  ["genericHearth:2"] = { en = "Familiar walls surround you again, and the noise outside fades away. It feels a little like coming home.",
    fr = "Des murs familiers vous entourent à nouveau, et le bruit du dehors s'estompe. Un peu comme rentrer chez soi." },
  ["genericHearth:3"] = { en = "Familiar surroundings take shape around you, and your heart finally settles. You're back, safe for a while.",
    fr = "Des lieux familiers se dessinent autour de vous, et votre cœur se pose enfin. Vous voilà de retour, à l'abri pour un moment." },
  ["genericHearth:4"] = { en = "A familiar place, at last. Your tired legs thank you, and you can finally catch your breath.",
    fr = "Un lieu familier, enfin. Vos jambes fatiguées vous remercient, et vous pouvez souffler un peu." },
  ["weather:1"] = { en = "The rain keeps falling. It drums on your shoulders and trickles down your face, and its fresh smell never leaves you.",
    fr = "La pluie tombe sans relâche. Elle tambourine sur vos épaules et ruisselle sur votre visage, et son odeur fraîche ne vous quitte plus." },
  ["weather:2"] = { en = "A smell of wet earth rises around you, deep and comforting. The world seems to breathe.",
    fr = "Une odeur de terre mouillée monte autour de vous, profonde et rassurante. Le monde semble respirer." },
  ["weather:3"] = { en = "Rain trickles down the back of your neck, cold and persistent. You hunch your shoulders, dreaming of a roof.",
    fr = "La pluie vous coule dans le cou, froide et insistante. Vous rentrez les épaules en rêvant d'un toit." },
  ["weather:4"] = { en = "Snowflakes settle on your sleeves and melt at once. Everything grows quiet, as if the world were holding its breath.",
    fr = "Des flocons se posent sur vos manches et fondent aussitôt. Tout devient silencieux, comme si le monde retenait son souffle." },
  ["weather:5"] = { en = "Your breath forms little clouds in the icy air. You rub your hands together to warm them.",
    fr = "Votre souffle forme de petits nuages dans l'air glacé. Vous frottez vos mains l'une contre l'autre pour les réchauffer." },
  ["weather:6"] = { en = "Sand stings your eyes and grits between your teeth. You shield your face with your arm, without much success.",
    fr = "Le sable vous pique les yeux et crisse entre vos dents. Vous vous protégez le visage du bras, sans grand succès." },
  ["weather:7"] = { en = "You squint against the flying sand. The wind whistles in your ears, and the horizon vanishes behind an ochre veil.",
    fr = "Vous plissez les yeux face au sable qui vole. Le vent siffle à vos oreilles, et l'horizon disparaît dans un voile ocre." },
  ["weatherChange:rainStart:1"] = { en = "The first drops fall, heavy and cold. The smell of rain spreads through the air at once.",
    fr = "Les premières gouttes tombent, lourdes et froides. Une odeur de pluie se répand aussitôt dans l'air." },
  ["weatherChange:rainStop:1"] = { en = "The rain stops. Everything is still dripping, and the washed air smells clean and fresh.",
    fr = "La pluie cesse. Tout ruisselle encore, et l'air lavé sent bon le frais." },
  ["weatherChange:snowStart:1"] = { en = "Snow begins to fall in big, silent flakes. Despite the cold, you can't help smiling.",
    fr = "La neige se met à tomber, en gros flocons silencieux. Malgré le froid, vous ne pouvez pas vous empêcher de sourire." },
  ["weatherChange:snowStop:1"] = { en = "The snow stops falling. The world stays white and still, as if frozen mid-breath.",
    fr = "La neige cesse de tomber. Le monde reste blanc et immobile, comme figé au milieu d'un souffle." },
  ["weatherChange:sandStart:1"] = { en = "The wind picks up and the sand starts to fly. You lower your head and squint, your heart tightening a little.",
    fr = "Le vent se lève et le sable se met à voler. Vous baissez la tête et plissez les yeux, le cœur un peu serré." },
  ["weatherChange:sandStop:1"] = { en = "The sandstorm finally dies down. You shake out your clothes and breathe freely again.",
    fr = "La tempête de sable retombe enfin. Vous secouez vos vêtements et respirez à nouveau librement." },
  ["biome:forest:arrive:1"] = { en = "The air smells of leaves and damp earth. Under the trees, your pace slows on its own, as if not to disturb the forest.",
    fr = "L'air sent les feuilles et la terre humide. Sous les arbres, votre pas ralentit tout seul, comme pour ne pas déranger la forêt." },
  ["biome:forest:arrive:2"] = { en = "Birdsong drifts down from the branches, cheerful and unruly. You catch yourself smiling.",
    fr = "Des chants d'oiseaux descendent des branches, joyeux et désordonnés. Vous vous surprenez à sourire." },
  ["biome:forest:ambient:1"] = { en = "Leaves rustle overhead, as if the forest were whispering. You find yourself listening without knowing why.",
    fr = "Les feuilles bruissent au-dessus de vous, comme si la forêt chuchotait. Vous tendez l'oreille sans savoir pourquoi." },
  ["biome:forest:ambient:3"] = { en = "An owl hoots in the dark, very close. The sound makes you jump, then draws a smile.",
    fr = "Une chouette hulule dans l'obscurité, tout près. Le son vous fait sursauter, puis vous arrache un sourire." },
  ["biome:forest:ambient:4"] = { en = "Light filters through the leaves, scattering golden patches on the ground. A moment of peace, nothing more.",
    fr = "La lumière filtre à travers les feuilles et pose des taches dorées sur le sol. Un instant de paix, tout simplement." },
  ["biome:forest:ambient:5"] = { en = "A squirrel darts up a trunk and watches you from a branch, tail twitching. You feel like an intruder.",
    fr = "Un écureuil file le long d'un tronc et vous observe depuis une branche, la queue frémissante. Vous avez l'impression de déranger." },
  ["biome:plains:arrive:1"] = { en = "The wind sweeps freely across the open land and tugs at your clothes. With so much horizon, you breathe more deeply.",
    fr = "Le vent balaie librement les grands espaces et tire sur vos vêtements. Devant tant d'horizon, vous respirez plus large." },
  ["biome:plains:ambient:1"] = { en = "The grass murmurs in the wind, in long waves running to the horizon. It's soothing to watch.",
    fr = "L'herbe murmure dans le vent, en longues vagues qui courent jusqu'à l'horizon. C'est apaisant à regarder." },
  ["biome:plains:ambient:2"] = { en = "A bird circles high above, carried by the wind. You follow it with your eyes for a while, a little envious.",
    fr = "Un oiseau tournoie tout là-haut, porté par le vent. Vous le suivez des yeux un moment, avec un brin d'envie.",
    when = { indoors = false, sky = true, night = false } },
  ["biome:plains:ambient:3"] = { en = "Crickets sing in the grass by the hundreds. The night becomes almost chatty.",
    fr = "Des grillons chantent dans l'herbe, par centaines. La nuit en devient presque bavarde." },
  ["biome:farmland:arrive:2"] = { en = "Dust rises from the dry fields and tickles your nose. The land here has been thirsty for a long time.",
    fr = "La poussière s'élève des champs secs et vous chatouille le nez. Ici, la terre a soif depuis longtemps." },
  ["biome:farmland:arrive:3"] = { en = "The wind smells of dry earth and old harvests. A slightly sad smell, that of fields left unharvested.",
    fr = "Le vent sent la terre sèche et les vieilles moissons. Une odeur un peu triste, celle des champs qu'on n'a pas récoltés." },
  ["biome:farmland:ambient:2"] = { en = "Dust stings your eyes and clings to your lips. You dream of a sip of cool water.",
    fr = "La poussière vous pique les yeux et se colle à vos lèvres. Vous rêvez d'une gorgée d'eau fraîche." },
  ["biome:farmland:ambient:3"] = { en = "The dry fields stretch as far as the eye can see, yellowed and silent. You feel rather alone in the middle of it all.",
    fr = "Les champs secs s'étendent à perte de vue, jaunis et silencieux. On se sent bien seul au milieu de tout ça.",
    when = { indoors = false, alone = true } },
  ["biome:farmland:ambient:4"] = { en = "Crickets sing in the dry grass, tireless. There's something reassuring about their song in the dark.",
    fr = "Des grillons chantent dans l'herbe sèche, inlassables. Leur chant a quelque chose de rassurant dans la nuit." },
  ["biome:farmland:ambient:5"] = { en = "The air smells of dry fields and dusty earth. Even the wind seems tired here.",
    fr = "L'air sent les champs secs et la terre poussiéreuse. Même le vent semble fatigué ici." },
  ["biome:farmland:ambient:6"] = { en = "It smells of dry grass, warmed by the day. A summery smell that makes you want to lie down in the shade.",
    fr = "Ça sent l'herbe sèche, chauffée par la journée. Une odeur d'été qui vous donne envie de vous allonger à l'ombre." },
  ["biome:farmland:ambient:7"] = { en = "The dry, cracked ground crunches under your feet like an old bread crust. Rain hasn't come this way in a long time.",
    fr = "Le sol sec et craquelé croustille sous vos pas, comme une vieille croûte de pain. La pluie n'est pas passée par ici depuis longtemps." },
  ["biome:farmland:ambient:8"] = { en = "A smell of hay drifts over from the farm, warm and comforting. It reminds you of childhood afternoons.",
    fr = "Une odeur de foin vous arrive de la ferme, chaude et rassurante. Elle vous rappelle des après-midi d'enfance." },
  ["biome:farmland:ambient:9"] = { en = "A whiff of manure hits your nose. Not very poetic, but it's the smell of land that's still being worked.",
    fr = "Une bouffée de fumier vous saute au nez. Pas très poétique, mais c'est l'odeur d'une terre qu'on travaille encore." },
  ["biome:hills:arrive:1"] = { en = "The path rises and falls with the hills, and your calves feel every bit of it. At the top of each climb, the view rewards you.",
    fr = "Le chemin monte et descend au gré des collines, et vos mollets le sentent passer. Au sommet de chaque montée, la vue vous récompense." },
  ["biome:hills:ambient:1"] = { en = "A cool wind comes down from the heights, smelling of grass and stone. You lift your head to breathe it in.",
    fr = "Un vent frais descend des hauteurs et sent l'herbe et la pierre. Vous redressez la tête pour mieux le respirer." },
  ["biome:hills:ambient:2"] = { en = "The grass on the hills shivers in the wind, and its soft rustling follows you step by step.",
    fr = "L'herbe des collines frissonne sous le vent, et ce doux bruissement vous accompagne pas à pas." },
  ["biome:mountain:arrive:1"] = { en = "The air is sharper up here, and each breath stings your lungs a little. You feel tiny, and yet very much alive.",
    fr = "L'air est plus vif ici, en altitude, et chaque respiration vous pique un peu les poumons. Vous vous sentez minuscule, et pourtant bien en vie." },
  ["biome:mountain:ambient:1"] = { en = "Pebbles clatter down the slope. Out of reflex, you look up at the rocks above you.",
    fr = "Des cailloux dévalent la pente avec un bruit sec. Par réflexe, vous levez les yeux vers les rochers au-dessus de vous." },
  ["biome:mountain:ambient:2"] = { en = "The wind howls between the peaks and rushes into your clothes. You grit your teeth and keep going.",
    fr = "Le vent hurle entre les sommets et s'engouffre dans vos vêtements. Vous serrez les dents et continuez." },
  ["biome:snow:arrive:2"] = { en = "The cold grabs you the moment you arrive and nips the tip of your nose. You hunch your head into your shoulders.",
    fr = "Le froid vous saisit dès votre arrivée et vous mord le bout du nez. Vous rentrez la tête dans les épaules." },
  ["biome:snow:arrive:3"] = { en = "Everything is muffled under the snow: sounds, colors, even your thoughts. A vast, white calm.",
    fr = "Tout est feutré sous la neige : les bruits, les couleurs, même vos pensées. Un calme blanc et immense." },
  ["biome:snow:ambient:1"] = { en = "Snow crunches under your feet, each step leaving a crisp print behind you. A strangely satisfying sound.",
    fr = "La neige crisse sous vos pas, et chacun laisse une empreinte bien nette derrière vous. Un son étrangement satisfaisant." },
  ["biome:snow:ambient:2"] = { en = "A gust lifts a veil of powdery snow that whips your face. You close your eyes, breathless.",
    fr = "Une rafale soulève un voile de neige poudreuse qui vous fouette le visage. Vous fermez les yeux, le souffle coupé." },
  ["biome:snow:ambient:3"] = { en = "Your fingers ache with the cold, and you tuck them under your arms to warm them. A fire would be welcome.",
    fr = "Vos doigts vous font mal à cause du froid, et vous les glissez sous vos bras pour les réchauffer. Vivement un feu." },
  ["biome:desert:arrive:2"] = { en = "Heat rises from the sand in shimmering waves, and the horizon starts to dance. Your mouth is already dry.",
    fr = "La chaleur monte du sable en vagues tremblantes, et l'horizon se met à danser. Votre bouche est déjà sèche." },
  ["biome:desert:arrive:3"] = { en = "The dry air catches in your throat from the very first breath. Here, every drop of water counts.",
    fr = "L'air sec vous accroche la gorge dès la première inspiration. Ici, chaque goutte d'eau compte." },
  ["biome:desert:ambient:1"] = { en = "Sand gets everywhere: into your clothes, your pockets, even under your nails. Truly everywhere.",
    fr = "Le sable s'infiltre partout : dans vos vêtements, vos poches, jusque sous vos ongles. Vraiment partout." },
  ["biome:desert:ambient:2"] = { en = "The sand shifts under your feet, and each step takes a little effort. The heat weighs on your shoulders.",
    fr = "Le sable glisse sous vos pas, et chaque pas vous demande un petit effort. La chaleur pèse sur vos épaules.",
    when = { indoors = false, moving = true, night = false } },
  ["biome:savanna:arrive:1"] = { en = "Dry grass crackles under your feet, golden and brittle. The warm wind smells of dust and sun.",
    fr = "L'herbe sèche craque sous vos pas, dorée et cassante. Le vent chaud sent la poussière et le soleil." },
  ["biome:savanna:arrive:2"] = { en = "The plains stretch out, golden and endless, beneath a vast sky. Here, freedom tastes a little like vertigo.",
    fr = "Les plaines s'étendent, dorées et sans fin, sous un ciel immense. Ici, la liberté a un goût de vertige.",
    when = { indoors = false, sky = true, night = false } },
  ["biome:savanna:ambient:1"] = { en = "A dusty wind sweeps the plains and makes you squint. You taste the dust on your lips.",
    fr = "Un vent poussiéreux balaie les plaines et vous fait plisser les yeux. Vous goûtez la poussière sur vos lèvres." },
  ["biome:savanna:ambient:2"] = { en = "Somewhere far away, an animal cries out. You stop for a second, listening, then go on your way.",
    fr = "Quelque part, très loin, un animal pousse un cri. Vous vous arrêtez une seconde, l'oreille tendue, puis reprenez votre route." },
  ["biome:badlands:arrive:1"] = { en = "A red dust clings to everything: your clothes, your skin, your throat. The land looks as if it burned a very long time ago.",
    fr = "Une poussière rouge colle à tout : à vos vêtements, à votre peau, à votre gorge. Le paysage semble avoir brûlé il y a très longtemps." },
  ["biome:badlands:ambient:1"] = { en = "The rocks throw back the heat of the day, and the air shimmers above them. You look around for some shade, in vain.",
    fr = "Les rochers renvoient la chaleur du jour, et l'air tremble au-dessus d'eux. Vous cherchez un peu d'ombre du regard, en vain." },
  ["biome:badlands:ambient:2"] = { en = "Dust devils dance in the distance like ochre ghosts. It's beautiful, and a little unsettling.",
    fr = "Des tourbillons de poussière dansent au loin, comme des fantômes ocre. Le spectacle est beau, et un peu inquiétant." },
  ["biome:canyon:arrive:1"] = { en = "A red dust clings to everything, and tall rock walls tower over you on every side. You feel tiny among these giants of stone.",
    fr = "Une poussière rouge colle à tout, et les hautes parois de roche vous dominent de toutes parts. Vous vous sentez minuscule entre ces géants de pierre." },
  ["biome:canyon:ambient:1"] = { en = "The rock walls throw back the heat of the day. The air is still and heavy, and you move more slowly.",
    fr = "Les parois de roche renvoient la chaleur du jour. L'air est immobile et lourd, et vous avancez plus lentement." },
  ["biome:jungle:arrive:1"] = { en = "The air is thick and humid, and every breath feels wet. Within a few steps, your clothes already cling to your skin.",
    fr = "L'air est épais et humide, et chaque inspiration semble mouillée. En quelques pas, vos vêtements vous collent déjà à la peau." },
  ["biome:jungle:arrive:2"] = { en = "An explosion of green surrounds you: leaves as wide as shields, vines, flowers in loud colors. Everything here grows too fast.",
    fr = "Une explosion de verdure vous entoure : des feuilles larges comme des boucliers, des lianes, des fleurs aux couleurs criardes. Tout ici pousse trop vite." },
  ["biome:jungle:ambient:1"] = { en = "Insects buzz relentlessly, and one brushes past your ear. You swat at the air, without much hope.",
    fr = "Les insectes bourdonnent sans relâche, et l'un d'eux vous frôle l'oreille. Vous chassez l'air de la main, sans grand espoir." },
  ["biome:jungle:ambient:2"] = { en = "Something stirs in the undergrowth, very close. You freeze, heart pounding, but nothing comes out of the leaves.",
    fr = "Quelque chose remue dans les sous-bois, tout près. Vous vous figez, le cœur battant, mais rien ne sort des feuilles." },
  ["biome:jungle:ambient:3"] = { en = "Sweat glues your clothes to your skin, and the heavy air smells of sap and humus. You'd give a lot for a breeze.",
    fr = "La sueur colle vos vêtements à votre peau, et l'air lourd sent la sève et l'humus. Vous donneriez cher pour une brise." },
  ["biome:swamp:arrive:1"] = { en = "A smell of rot and stagnant water catches in your throat. You breathe through your mouth, hoping to get used to it quickly.",
    fr = "Une odeur de pourriture et d'eau stagnante vous prend à la gorge. Vous respirez par la bouche, en espérant vous y habituer vite." },
  ["biome:swamp:ambient:1"] = { en = "Frogs croak somewhere in the reeds, in an unruly chorus. The swamp is never truly silent.",
    fr = "Des grenouilles coassent quelque part dans les roseaux, en chœur désordonné. Le marais n'est jamais vraiment silencieux." },
  ["biome:swamp:ambient:2"] = { en = "Mosquitoes whine around your ears. You slap the back of your neck, to no avail.",
    fr = "Des moustiques vous tournent autour des oreilles avec un sifflement aigu. Vous vous donnez une claque sur la nuque, sans résultat." },
  ["biome:marsh:arrive:1"] = { en = "The spongy ground gurgles under your feet, and cold water seeps in everywhere. You move carefully, damp to the bone.",
    fr = "Le sol spongieux gargouille sous vos pas, et l'eau froide s'infiltre partout. Vous avancez avec précaution, l'humidité jusqu'aux os." },
  ["biome:marsh:ambient:1"] = { en = "Frogs croak in the reeds, and the air smells of silt and still water. A grey, soggy landscape, yet strangely alive.",
    fr = "Des grenouilles coassent dans les roseaux, et l'air sent la vase et l'eau dormante. Un paysage gris et mouillé, mais étrangement vivant." },
  ["biome:coast:arrive:1"] = { en = "The sea air tastes of salt, and the wind brings a smell of seaweed and open water. Something in you relaxes.",
    fr = "L'air marin a un goût de sel, et le vent vous apporte une odeur d'algues et de large. Quelque chose en vous se détend." },
  ["biome:coast:ambient:1"] = { en = "A gull's cry comes in from the sea, sharp and free. You look out toward the open water with a sudden urge to travel.",
    fr = "Le cri d'une mouette arrive de la mer, perçant et libre. Vous levez les yeux vers le large, avec une soudaine envie de voyage." },
  ["biome:gloom:arrive:2"] = { en = "A shiver that has nothing to do with the weather runs down your spine. Without quite knowing why, you tighten your grip on your weapon.",
    fr = "Un frisson qui n'a rien à voir avec le temps vous parcourt l'échine. Sans trop savoir pourquoi, vous resserrez la main sur votre arme." },
  ["biome:gloom:arrive:3"] = { en = "The light seems weaker here, as if smothered. The colors have faded, and a dull sadness hangs in the air.",
    fr = "La lumière semble plus faible ici, comme étouffée. Les couleurs ont pâli, et une tristesse sourde flotte dans l'air." },
  ["biome:gloom:ambient:1"] = { en = "A crow caws somewhere in the dark branches. The sound chills you for a moment.",
    fr = "Un corbeau croasse quelque part dans les branches sombres. Le son vous glace un instant." },
  ["biome:gloom:ambient:2"] = { en = "You could swear something is watching you. You turn around: nothing. Just shadow and silence.",
    fr = "Vous jureriez que quelque chose vous observe. Vous vous retournez : rien. Juste l'ombre et le silence.",
    when = { indoors = false, alone = true } },
  ["biome:gloom:ambient:3"] = { en = "The silence here is heavy, so thick you could hear your own heartbeat. You don't dare break it.",
    fr = "Le silence est pesant ici, si épais qu'on entendrait son propre cœur. Vous n'osez pas le briser." },
  ["biome:plague:arrive:1"] = { en = "The air carries a faint sickly smell, sweetish and nauseating. Your stomach knots.",
    fr = "L'air porte une légère odeur maladive, douceâtre et écœurante. Votre estomac se noue." },
  ["biome:plague:ambient:1"] = { en = "The grass grows grey and brittle here, and nothing seems truly alive. You avoid touching it.",
    fr = "L'herbe pousse grise et cassante ici, et rien ne semble vraiment vivant. Vous évitez d'y toucher." },
  ["biome:plague:ambient:2"] = { en = "You catch yourself breathing through your mouth to escape the smell of sickness. You can't wait to leave this place.",
    fr = "Vous vous surprenez à respirer par la bouche, pour ne plus sentir cette odeur de maladie. Vivement que vous quittiez cet endroit." },
  ["biome:wasteland:arrive:1"] = { en = "Little grows here. The earth is dry and bare, and the wind brings nothing but dust. A landscape that tugs at your heart.",
    fr = "Pas grand-chose ne pousse ici. La terre est sèche et nue, et le vent n'apporte que de la poussière. Un paysage qui vous serre le cœur." },
  ["biome:wasteland:ambient:1"] = { en = "A dry wind scatters gravel across the ground with a sound like hail. You squint, your throat dry.",
    fr = "Un vent sec éparpille du gravier sur le sol avec un petit bruit de grêle. Vous plissez les yeux, la gorge sèche." },
  ["biome:volcanic:arrive:1"] = { en = "The air smells of sulfur and ash, and stings your throat with every breath. The land itself seems angry.",
    fr = "L'air sent le soufre et la cendre, et vous pique la gorge à chaque inspiration. La terre elle-même semble en colère." },
  ["biome:volcanic:ambient:1"] = { en = "Ash drifts down like grey snow and settles on your shoulders. There is nothing gentle about this snow.",
    fr = "La cendre retombe comme une neige grise et se dépose sur vos épaules. Il n'y a rien de doux dans cette neige-là." },
  ["biome:volcanic:ambient:2"] = { en = "The ground is warm under your feet, even through your soles. You don't feel like standing still for long.",
    fr = "Le sol est chaud sous vos pieds, même à travers vos semelles. Vous n'avez pas envie de rester immobile bien longtemps." },
  ["biome:corrupted:arrive:1"] = { en = "Something is very wrong with this forest. The air smells of rotten sap, and a dull unease knots your stomach.",
    fr = "Quelque chose ne tourne vraiment pas rond dans cette forêt. L'air sent la sève pourrie, et un malaise sourd vous noue le ventre." },
  ["biome:corrupted:ambient:1"] = { en = "The trees here look sick and twisted, as if frozen in silent pain. You look away.",
    fr = "Les arbres ici semblent malades et tordus, comme figés dans une douleur muette. Vous détournez les yeux." },
  ["biome:city:ambient:1"] = { en = "The city never really sleeps. Even at night, you can feel it living around you, and there's something reassuring about that.",
    fr = "La ville ne dort jamais vraiment. Même la nuit, on la sent vivre autour de vous, et ça a quelque chose de rassurant." },
  ["biome:city:ambient:2"] = { en = "Voices and footsteps fill the air, mixed with the smells of the city. You let yourself be carried along by the bustle for a moment.",
    fr = "Des voix et des bruits de pas emplissent l'air, mêlés aux odeurs de la ville. Vous vous laissez porter un instant par cette agitation." },
  ["biome:city:ambient:3"] = { en = "The streets are strangely quiet, and the silence feels unreal. You catch yourself walking more softly.",
    fr = "Les rues sont étrangement calmes, et ce silence a quelque chose d'irréel. Vous vous surprenez à marcher plus doucement.",
    when = { indoors = false, moving = true, crowd = "quiet" } },
  ["biome:forge:arrive:1"] = { en = "Warm air and a smell of hot metal greet you, and the rumble of the forges hums in your chest. Here, the mountain has a heart, and it beats.",
    fr = "Un air chaud et une odeur de métal chaud vous accueillent, et le grondement des forges vibre jusque dans votre poitrine. Ici, la montagne a un cœur, et il bat." },
  ["biome:forge:ambient:1"] = { en = "The air tastes of soot, and a fine black dust settles on your skin. A good bath wouldn't go amiss.",
    fr = "L'air a un goût de suie, et une fine poussière noire se dépose sur votre peau. Un bon bain ne serait pas de refus." },
  ["biome:forge:ambient:2"] = { en = "Somewhere, a hammer rings on an anvil, steady as a heartbeat. There's something soothing in the rhythm.",
    fr = "Quelque part, un marteau résonne sur une enclume, régulier comme un battement de cœur. Ce rythme a quelque chose d'apaisant." },
  ["biome:undercity:arrive:1"] = { en = "The air here is damp and stale, heavy with the smell of wet stone and something darker. You'd rather not know what.",
    fr = "L'air ici est humide et confiné, chargé d'une odeur de pierre mouillée et de quelque chose de plus sombre. Vous n'avez pas envie de savoir quoi." },
  ["biome:undercity:ambient:1"] = { en = "Water drips somewhere in the dark, slow and steady. Each drop seems to count the passing time.",
    fr = "De l'eau goutte quelque part dans l'obscurité, lente et régulière. Chaque goutte semble compter le temps qui passe." },
  ["zone:1412:arrive:1"] = { en = "Mulgore's tall grass ripples around you, and the wind smells of earth and warm grass. Everything here breathes peace.",
    fr = "Les hautes herbes de Mulgore ondulent autour de vous, et le vent sent la terre et l'herbe tiède. Ici, tout respire la paix." },
  ["zone:1417:arrive:1"] = { en = "Tall grass ripples across the Arathi Highlands, and the wind carries the smell of open land. They say old stones here still remember a forgotten kingdom.",
    fr = "Les hautes herbes ondulent sur les hauteurs d'Arathi, et le vent porte l'odeur des grands espaces. On dit que de vieilles pierres, ici, se souviennent d'un royaume oublié." },
  ["zone:1429:arrive:1"] = { en = "Elwynn's gentle hills roll away under the trees, green and welcoming. The air smells of grass and resin, and at last you breathe freely.",
    fr = "Les douces collines d'Elwynn s'étendent sous les arbres, vertes et accueillantes. L'air sent l'herbe et la résine, et vous respirez enfin." },
  ["zone:1453:arrive:1"] = { en = "Stormwind's white stone gleams in the sun, so bright it makes you squint. Without thinking, you stand a little straighter, as if to live up to it.",
    fr = "La pierre blanche de Hurlevent luit au soleil, si claire qu'elle vous fait plisser les yeux. Sans y penser, vous vous redressez, comme pour être à la hauteur.",
    when = { indoors = false, sky = true, night = false, weather = "clear" } },
  ["spot:sw_dwarven_forge:ambient:1"] = { en = "The forge's heat stings your cheeks, and the smell of hot iron fills your nose. Here, even the air seems hard at work.",
    fr = "La chaleur de la forge vous pique les joues, et l'odeur de fer chaud vous emplit le nez. Ici, même l'air semble travailler." },
  ["spot:sw_dwarven_forge_fire:ambient:1"] = { en = "The embers glow red, and the air shimmers above them. There's something hypnotic about their light.",
    fr = "Les braises rougeoient, et l'air tremble au-dessus d'elles. Leur lueur a quelque chose d'hypnotique." },
  ["spot:wf_sentinel_inn:ambient:1"] = { en = "The wind whistles through the holes in the roof and makes the candle flames shiver. You pull your clothes tighter around you.",
    fr = "Le vent siffle à travers les trous du toit et fait frissonner les flammes des bougies. Vous resserrez vos vêtements contre vous." },
  ["spot:wf_sentinel_inn:ambient:2"] = { en = "Loose planks creak overhead with every gust. You look up, hoping it all holds a little longer.",
    fr = "Des planches mal fixées grincent au-dessus de vous à chaque rafale. Vous levez les yeux en espérant que tout tiendra encore un moment." },
  ["spot:wf_sentinel_inn:ambient:3"] = { en = "The candles flicker in the draughts, and shadows dance on the plank walls. The place feels fragile, and precious.",
    fr = "Les bougies vacillent dans les courants d'air, et les ombres dansent sur les murs de planches. L'endroit a quelque chose de fragile et de précieux." },
  ["spot:wf_sentinel_inn:ambient:4"] = { en = "Through the broken roof, a few stars are showing. There are worse ceilings.",
    fr = "Par le toit éventré, on aperçoit quelques étoiles. Il y a pire, comme plafond." },
  ["spot:wf_sentinel_inn:ambient:5"] = { en = "Here, people make do with what little they have. And yet, despite the hardship, they stick together, and it warms your heart.",
    fr = "Ici, on fait avec le peu qu'on a. Et pourtant, malgré la misère, on se serre les coudes, et ça vous réchauffe le cœur." },
  ["sub:sw_trade:ambient:1"] = { en = "Merchants' signs creak in the breeze, and a smell of new leather and polished wood drifts out of the shops. You want to look at everything.",
    fr = "Les enseignes des marchands grincent dans la brise, et une odeur de cuir neuf et de bois ciré s'échappe des boutiques. Vous avez envie de tout regarder." },
  ["sub:sw_canals:ambient:1"] = { en = "Water laps against the stone of the canals, and the air smells of damp and moss. The sound of the water gently soothes you.",
    fr = "L'eau clapote contre la pierre des canaux, et l'air sent l'humidité et la mousse. Le bruit de l'eau vous apaise doucement." },
  ["sub:sw_mage:ambient:1"] = { en = "The air tingles faintly with magic, and a light shiver runs along your arms. Here, even the air seems to know things.",
    fr = "L'air picote légèrement de magie, et un léger frisson vous parcourt les bras. Ici, même l'air semble savoir des choses." },
  ["sub:sw_dwarven:ambient:2"] = { en = "A smell of coal smoke and hot iron hangs over the district. It reminds you this city was built with sweat and hammers.",
    fr = "Une odeur de fumée de charbon et de fer chaud flotte sur le quartier. Elle vous rappelle que cette ville a été bâtie à la sueur et au marteau." },
  ["sub:sw_dwarven:ambient:3"] = { en = "Thick smoke rises from the forges and makes you squint. The whole district seems to work without ever stopping.",
    fr = "Une épaisse fumée s'élève des forges et vous fait plisser les yeux. Le quartier tout entier semble travailler sans jamais s'arrêter." },
  ["sub:sw_dwarven:ambient:4"] = { en = "A whiff of gunpowder mixes with the forge smoke. You hope nobody is testing their guns too close by.",
    fr = "Une pointe de poudre se mêle à la fumée des forges. Vous espérez que personne ne teste ses fusils trop près d'ici." },
  ["sub:sw_dwarven:ambient:5"] = { en = "Soot drifts in the air and settles on your sleeves. You brush it off, in vain.",
    fr = "De la suie flotte dans l'air et se dépose sur vos manches. Vous la chassez d'un revers de main, en vain." },
  ["sub:sw_cathedral:ambient:1"] = { en = "The great cathedral towers over the square, white and majestic. In front of it, you lower your voice without thinking.",
    fr = "La grande cathédrale domine la place, blanche et majestueuse. Devant elle, vous baissez la voix sans y penser." },
  ["sub:wf_pumpkins:ambient:1"] = { en = "Fat orange pumpkins lie scattered between the rows, round and shiny. Autumn seems to have settled here for good.",
    fr = "De gros potirons orange sont éparpillés entre les rangs, ronds et luisants. L'automne semble s'être installé ici pour de bon." },
  ["sub:wf_pumpkins:ambient:2"] = { en = "A sweetish smell of overripe pumpkin hangs over the field. A little sickly, but strangely comforting.",
    fr = "Une odeur douceâtre de potiron trop mûr flotte sur le champ. Un peu écœurante, mais étrangement réconfortante." },
  ["sub:wf_pumpkins:ambient:3"] = { en = "A smell of machine oil and hot metal hangs in the air. You glance around, watching out for the mechanical harvesters.",
    fr = "Une odeur d'huile de machine et de métal chaud flotte dans l'air. Vous jetez un œil autour de vous, à l'affût des moissonneurs mécaniques." },
  ["sub:wf_pumpkins:ambient:4"] = { en = "Somewhere in the field, gears creak and grind. The sound puts you on guard at once.",
    fr = "Quelque part dans le champ, des engrenages grincent. Le bruit vous met aussitôt sur vos gardes." },
  ["sub:goldshire:ambient:1"] = { en = "The smell of the inn's kitchen drifts across the road: stew, bread and beer. Your stomach protests loudly.",
    fr = "L'odeur des cuisines de l'auberge flotte jusqu'au chemin : ragoût, pain et bière. Votre estomac proteste bruyamment." },
  ["sub:if_forge:arrive:1"] = { en = "The heat of the Great Forge wraps around you all at once, and the rumble of molten metal makes the air hum. You are at the beating heart of Ironforge.",
    fr = "La chaleur de la Grande Forge vous enveloppe d'un coup, et le grondement du métal en fusion fait vibrer l'air. Vous voilà au cœur battant de Forgefer." },
  ["sub:if_forge:ambient:1"] = { en = "Molten metal glows in the great channels, bathing the hall in orange light. The heat dries your eyes, but the sight is worth it.",
    fr = "Le métal en fusion rougeoie dans les grandes rigoles et baigne la salle d'une lueur orangée. La chaleur vous sèche les yeux, mais le spectacle en vaut la peine." },
  ["sub:if_forge:ambient:2"] = { en = "The heat of the Great Forge surrounds you, and a smell of metal and coal fills your throat. Here, legends are forged.",
    fr = "La chaleur de la Grande Forge vous enveloppe, et une odeur de métal et de charbon vous emplit la gorge. Ici, on forge des légendes." },
}
